#!/usr/bin/env node
// Generates the per-file self-explaining manifest for each workflow knowledge JSONL:
//   .claude/workflows/<wf>.knowledge.jsonl  ->  <wf>.knowledge.manifest.json
//
// A manifest is a "dataset card" (purpose/schema/enums/version/see_also) sitting
// next to the JSONL so a cold reader understands the file without grepping. The 12
// workflow files share ONE record schema, so this emits them from a single template
// (edit the template here -> re-run; do NOT hand-edit the generated files). Per-model
// experiment logs (python/.../models/**/kb.jsonl -> kb.manifest.json) are
// hand-maintained and NOT touched by this script.
//
// The checker (check-workflow-patterns.mjs) enforces that every kb.jsonl has a
// sibling manifest and that the declared record_schema covers the data (drift = exit 1).
import { readdirSync, writeFileSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const WF_DIR = join(__dirname, "..", ".claude", "workflows");

// Canonical workflow-knowledge record schema (mirrors _shared-patterns.md
// "Record schema"). One entry per top-level key — the checker's drift rule requires
// record_schema[].name to cover every key present in the data.
const RECORD_SCHEMA = [
  { name: "schema_version", type: "int",    desc: "record schema version (migration key)" },
  { name: "id",             type: "string", desc: "<family>:<slug> — stable dedup/supersession key" },
  { name: "type",           type: "string", desc: "pattern | lever | avoid | gotcha | false_positive | metric" },
  { name: "title",          type: "string", desc: "headline" },
  { name: "detail",         type: "string", desc: "what was learned, actionable, <=~160 chars" },
  { name: "tags",           type: "array",  desc: "free-form tags" },
  { name: "dimension",      type: "string", desc: "optional review-family dimension" },
  { name: "confidence",     type: "number", desc: "0..1" },
  { name: "status",         type: "string", desc: "active | superseded | retired" },
  { name: "superseded_by",  type: "string", desc: "id of the replacing record, or null" },
  { name: "evidence",       type: "object", desc: "{ run_ids:[<=8 newest], occurrences, first_seen, last_seen }" },
  { name: "extracted_at",   type: "string", desc: "runId of the last extraction (NO Date.now — threaded from RUN_ID)" },
];

function workflowManifest(wfName) {
  return {
    manifest_version: 1,
    file: `${wfName}.knowledge.jsonl`,
    kind: "workflow-knowledge",
    purpose: `Distilled, committed, per-workflow knowledge for ${wfName} — pattern/lever/avoid/gotcha/false_positive/metric records loaded at Resolve (loadKnowledge) and rewritten at Persist (extractKnowledge). The committed, cross-machine superset of the ephemeral history/${wfName}/.`,
    record_version_field: "schema_version",
    record_version: 1,
    produced_by: `extractKnowledge() in ${wfName}.js (Persists, after saveHistory).`,
    consumed_by: `loadKnowledge() in ${wfName}.js (Resolve) — injects active records' digest into the run. Also scripts/workflow-knowledge-manifest.mjs (the MANIFEST.md coverage matrix).`,
    record_schema: RECORD_SCHEMA,
    enums: {
      type: ["pattern", "lever", "avoid", "gotcha", "false_positive", "metric"],
      status: ["active", "superseded", "retired"],
    },
    findings: "The ACTIVE records in THIS file are the findings (loadKnowledge filters status=active; superseded/retired are kept for audit but hidden). Raw per-run detail stays in the gitignored history/ dir.",
    see_also: [
      ".claude/workflows/_shared-patterns.md#workflow-knowledge-colocated-committed-jsonl",
      ".claude/workflows/_shared-patterns.md#kb-manifest-self-explaining-jsonl",
      ".claude/workflows/MANIFEST.md",
      "memory: workflow-colocated-knowledge-jsonl",
    ],
    notes: "DIFFERENT artifact from per-model experiment logs (python/.../models/**/kb.jsonl), which are raw A/B measurements with their own kb.manifest.json. This file is GENERATED by scripts/kb-manifest-gen.mjs — do not hand-edit.",
  };
}

const jsonlFiles = readdirSync(WF_DIR)
  .filter((f) => f.endsWith(".knowledge.jsonl"))
  .sort();

let written = 0;
for (const f of jsonlFiles) {
  const wfName = f.replace(/\.knowledge\.jsonl$/, "");
  const manifestPath = join(WF_DIR, `${wfName}.knowledge.manifest.json`);
  const manifest = workflowManifest(wfName);
  writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n");
  // record count for the summary line
  let records = 0;
  try {
    records = readFileSync(join(WF_DIR, f), "utf8").split("\n").filter((l) => l.trim()).length;
  } catch {}
  console.log(`  ${wfName}.knowledge.manifest.json  (data: ${records} records)`);
  written++;
}
console.log(`\nGenerated ${written} workflow manifest(s) → ${WF_DIR}`);
console.log("Per-model kb.manifest.json (e.g. dark-beast-dbzit9) is hand-maintained — not touched.");
